  final int top;
  final int width;
  final int height;

  Rect(this.left, this.top, this.width, this.height);

  int get right => left + width;
  int get bottom => top + height;
}

Future<List<Uint8List>> sliceImageIntoFour(String imagePath) async {
  try {
    // Read the image file from the specified path
    final File imageFile = File(imagePath);
    if (!imageFile.existsSync()) {
      throw FileSystemException('File not found at path: $imagePath');
    }

    // Read the image file as bytes
    final Uint8List imageData = await imageFile.readAsBytes();

    // Decode the image data
    final img.Image? image = img.decodeImage(imageData);
    if (image == null) {
      throw Exception('Unsupported image format or invalid image data.');
    }

    // Get the dimensions of the image
    final int width = image.width;
    final int height = image.height;

    // Calculate the center point
    final int centerX = width ~/ 2;
    final int centerY = height ~/ 2;

    // Explicitly divide the image into four equal parts from the center
    final List<Rect> regions = [
      Rect(0, 0, centerX, centerY),        // Top-left
      Rect(centerX, 0, width - centerX, centerY),  // Top-right
      Rect(0, centerY, centerX, height - centerY),  // Bottom-left
      Rect(centerX, centerY, width - centerX, height - centerY), // Bottom-right
    ];

    // Create a list to hold the four sliced images in bytes format
    List<Uint8List> slicedImagesBytes = [];

    // Create a new image for each slice
    for (var region in regions) {
      final img.Image slicedImage = img.copyCrop(image, region.left, region.top, region.width, region.height);

      // Convert the sliced image to bytes
      final Uint8List slicedImageBytes = Uint8List.fromList(img.encodePng(slicedImage));
      slicedImagesBytes.add(slicedImageBytes);
    }

    return slicedImagesBytes;
  } catch (e) {
    throw Exception('Error processing image: $e');
  }
}

