                   backgroundColor: ['rgba(75, 192, 192, 0.2)', 'rgba(153, 102, 255, 0.2)'],
                   borderColor: ['rgba(75, 192, 192, 1)', 'rgba(153, 102, 255, 1)'],
                   borderWidth: 1
               }]
           };

           const options = {
               scales: {
                   xAxes: [{
                       type: 'linear',
                       position: 'bottom'
                   }],
                   yAxes: [{
                       type: 'linear'
                   }]
               }
           };

           new Chart(ctx, {
               type: 'scatter',
               data: data,
               options: options
           });
       }
